import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Playwright App Shell","description":"","frontmatter":{"title":"Playwright App Shell"},"headers":[],"relativePath":"operations/playwright-app-shell.md","filePath":"operations/playwright-app-shell.md","lastUpdated":1793170193000}'),i={name:"operations/playwright-app-shell.md"};function d(l,t,s,n,p,h){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="playwright-app-shell" tabindex="-1">Playwright App Shell <a class="header-anchor" href="#playwright-app-shell" aria-label="Permalink to &quot;Playwright App Shell&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">正確網址</p><p><strong>Canonical：</strong> <a href="https://strawcoding.github.io/operations/playwright-app-shell" target="_blank" rel="noreferrer">https://strawcoding.github.io/operations/playwright-app-shell</a></p></div><h2 id="目的" tabindex="-1">目的 <a class="header-anchor" href="#目的" aria-label="Permalink to &quot;目的&quot;">​</a></h2><p>網頁／UI 驗收必須證明使用者看得到的 <strong>實際 route + app chrome</strong>，不是 welcome 畫面或元件單元假陽性。</p><h2 id="硬閘" tabindex="-1">硬閘 <a class="header-anchor" href="#硬閘" aria-label="Permalink to &quot;硬閘&quot;">​</a></h2><ol><li><strong>bypass onboarding</strong> 進有 BottomNav 的 app shell（<code>[data-testid=bottom-nav]</code>）。</li><li>驗 FontAwesome icon 與目標頁，不要在 welcome／post-setup intro 就 PASS。</li><li>多步驟／全螢幕流程：檢查 BottomNav／safe-area <strong>有沒有遮住</strong>表單或主 CTA。</li><li>長表單 route 應設 <code>meta.hideAppChrome</code>（<code>App.vue</code> 的 <code>full-screen-route</code>），Playwright 斷言該頁 <strong>沒有</strong> BottomNav。</li></ol><h2 id="套件對照" tabindex="-1">套件對照 <a class="header-anchor" href="#套件對照" aria-label="Permalink to &quot;套件對照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>改動</th><th>suite</th><th>CI</th></tr></thead><tbody><tr><td>首頁／導覽／功能列表／設定殼</td><td><code>npm run playwright:ui-layout --prefix frontend</code></td><td>有</td></tr><tr><td>預算儲蓄</td><td><code>playwright:budget-save</code></td><td>有</td></tr><tr><td>分析匯出</td><td><code>playwright:analysis-export</code></td><td>有</td></tr><tr><td>載具同步</td><td><code>playwright:carrier-sync</code></td><td>有</td></tr><tr><td>跨月預算</td><td><code>playwright:budget-cross-month</code></td><td>有</td></tr><tr><td>發薪週期</td><td><code>playwright:budget-pay-cycle</code></td><td>有</td></tr><tr><td>銀行同步設定</td><td><code>playwright:bank-sync</code></td><td><strong>有（本方案納入 CI）</strong></td></tr></tbody></table><p><code>closeout:verify</code> 不含 Playwright。Hermes closeout 要加 <code>--playwright &lt;suite&gt;</code>。</p><h2 id="共用-onboarding" tabindex="-1">共用 onboarding <a class="header-anchor" href="#共用-onboarding" aria-label="Permalink to &quot;共用 onboarding&quot;">​</a></h2><p>各 <code>frontend/scripts/playwright-*.mjs</code> 有自己的 <code>completeOnboarding()</code>。改 welcome 文案會全套一起炸——改 wizard 時必須重跑相關 suite。</p><p>Browsers 路徑：CI 用 <code>PLAYWRIGHT_BROWSERS_PATH</code> 指向 <code>backend/.server-data/playwright-browsers</code>。本機：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright:install-browsers</span></span></code></pre></div><h2 id="引用" tabindex="-1">引用 <a class="header-anchor" href="#引用" aria-label="Permalink to &quot;引用&quot;">​</a></h2><ul><li><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/frontend/scripts/playwright-ui-layout.mjs" target="_blank" rel="noreferrer"><code>frontend/scripts/playwright-ui-layout.mjs</code></a></li><li><a href="/operations/testing-and-verification.html">Testing-And-Verification</a></li><li><a href="/operations/ci-cd-and-gates.html">CI-CD-And-Gates</a></li></ul>',15)])])}const u=a(i,[["render",d]]);export{g as __pageData,u as default};
